//! Standalone TypeScript-bindings exporter — the no-dev-server regen path.
//!
//! `src/lib/ipc/bindings.ts` is generated by tauri-specta from the Rust
//! command/type signatures. The only other place it gets written is the
//! `#[cfg(debug_assertions)]` export at `pnpm tauri dev` startup — which means
//! a full app launch (window, Vite port, data dir). This binary drives the same
//! `lucerna_lib::specta_builder()` and exits immediately, so bindings can be
//! regenerated without any of that.
//!
//! Usage (from `src-tauri/`):
//! - `cargo run --bin export_bindings`            — regenerate in place.
//! - `cargo run --bin export_bindings -- --check` — CI freshness guard: exit 1
//!   if the committed file is stale (no write).
//!
//! Note: this links `tauri::Wry` (via the builder), so it must run from
//! `target/<profile>/` where the webview loader library sits next to it — which
//! `cargo run` does. A `tests/` integration binary cannot (it runs from
//! `target/<profile>/deps/`, away from that library → entrypoint-not-found).

use std::error::Error;
use std::path::{Path, PathBuf};

use specta_typescript::Typescript;

/// Resolved relative to this crate (`src-tauri/`) at compile time, so the
/// output path is correct regardless of the process CWD.
fn bindings_path() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../src/lib/ipc/bindings.ts")
}

fn main() -> Result<(), Box<dyn Error>> {
    let target = bindings_path();
    let check = std::env::args().any(|a| a == "--check");

    if check {
        let tmp = std::env::temp_dir().join("lucerna-bindings-freshness-check.ts");
        lucerna_lib::specta_builder().export(Typescript::default(), &tmp)?;
        if std::fs::read_to_string(&tmp)? != std::fs::read_to_string(&target)? {
            eprintln!(
                "bindings.ts is STALE — a Rust command/type changed without regenerating.\n\
                 Run: cargo run --manifest-path src-tauri/Cargo.toml --bin export_bindings"
            );
            std::process::exit(1);
        }
        println!("bindings.ts is up to date.");
    } else {
        lucerna_lib::specta_builder().export(Typescript::default(), &target)?;
        println!("Regenerated {}", target.display());
    }
    Ok(())
}
